//! Golden tests of the block oracle harness itself (`tests/common/block_scenario.rs`) against the real vanilla level.
//! Scenarios: `tests/oracle/scenarios/blk_harness_*.txt`, fixtures from `scripts/block-oracle.sh NAME`.
use crate::common;

use crate::common::block_scenario::check;

#[test]
fn generated_nether_block_light() {
    check("blk_harness_light_nether");
}

/// The nether around the fortress of seed 1 is generated by neighbouring chunks writing lava and magma into chunks that already
/// initialised their light (vanilla's own output of this area varies between runs, so only the invariant is checked): every
/// lava and magma block carries at least its own emission.
#[test]
fn generated_nether_emitters_are_lit() {
    let lines = common::block_scenario::run_scenario_text(
        "level normal\nstructures true\nseed 1\ndimension the_nether\npreload 0\ndifficulty normal\n\
         spawn_player Steve survival -96.5 70 205.5 0 0\ntick 100\n\
         dump blocks:-80,50,140,-56,66,170 lights:-80,50,140,-56,66,170\n",
    );
    let light = |l: &str| -> i32 {
        let t: Vec<&str> = l.split(' ').collect();
        t[4].trim_start_matches("block=").parse().unwrap()
    };
    let mut lights = std::collections::HashMap::new();
    for l in lines.iter().filter(|l| l.starts_with("LIGHT ")) {
        let t: Vec<&str> = l.split(' ').collect();
        lights.insert((t[1], t[2], t[3]), light(l));
    }
    let mut emitters = 0;
    for l in lines.iter().filter(|l| l.starts_with("B ")) {
        let t: Vec<&str> = l.split(' ').collect();
        let emission = if t[4].starts_with("minecraft:lava") {
            15
        } else if t[4] == "minecraft:magma_block" {
            3
        } else {
            continue;
        };
        emitters += 1;
        let got = lights.get(&(t[1], t[2], t[3])).copied().unwrap_or(0);
        assert!(got >= emission, "{l}: block light {got}");
    }
    assert!(emitters > 50, "only {emitters} emitters in the box");
}

